var index=0;const sdWebData=document.getElementById("sdWebDataID"),spiner=document.getElementById("spinerID"),containerFiles=document.getElementById("containerFilesID"),containerInfo=document.getElementById("containerInfoID"),volumeName=document.getElementById("volumeNameID"),ocupiedSize=document.getElementById("ocupiedSizeID"),totalSpace=document.getElementById("totalSpaceID"),containerSpinner=document.getElementById("containerSpinnerID");function formatSizeSameScale(total,occupied){const units=["Bytes","KB","MB","GB","TB"];let index=0,size=total;for(;size>=1024&&index<units.length-1;)size/=1024,index++;const totalInScale=total/Math.pow(1024,index),occupiedInScale=occupied/Math.pow(1024,index);return{total:`${totalInScale.toFixed(2)} ${units[index]}`,occupied:`${occupiedInScale.toFixed(2)} ${units[index]}`}}function getFTPData(){containerSpinner.style.display="block",urlEncodedData=new URLSearchParams,urlEncodedData.append("index",index),fetch("/ftp_get_data",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:urlEncodedData.toString()}).then((response=>{if(response.ok)return response.text();throw new Error(response.status+" "+response.statusText)})).then((data=>{console.log(data),containerSpinner.style.display="none",sdWebData.innerHTML="",containerInfo.style.display="block";const params=new URLSearchParams(data),volume_name=params.get("volume_name"),freesize=parseInt(params.get("freesize")),totalsize=parseInt(params.get("totalsize")),formattedSizes=formatSizeSameScale(totalsize,totalsize-freesize);volumeName.innerHTML=volume_name,ocupiedSize.innerHTML=formattedSizes.occupied,totalSpace.innerHTML=formattedSizes.total;const filenames=params.getAll("filename"),filesizes=params.getAll("filesize");filenames.forEach(((filename,index)=>{const filesize=filesizes[index],fileDiv=document.createElement("div");fileDiv.className="m-1",fileDiv.innerHTML=`\n            <div class="r">\n                <div class="cl cl-nw">${filename}</div>\n                <div class="cl cl-nw">${filesize} bytes</div>\n                <div class="cl cl-nw">\n                    <div class="r j-c">\n                        <div class="btn btn-ss btn-i" onclick="DownloadFile('${filename}')">\n                            <i>&#8595;</i>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        `,containerFiles.appendChild(fileDiv)}))})).catch((error=>{spiner.style.display="none",sdWebData.className="bd bd-dg",sdWebData.innerHTML=error}))}function DownloadFile(filename){urlEncodedData=new URLSearchParams,urlEncodedData.append("filename",filename),console.log(urlEncodedData.toString()),fetch("/ftp_get_file",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:urlEncodedData.toString()}).then((response=>{if(response.ok)return response.blob();throw new Error(response.status+" "+response.statusText)})).then((blob=>{const downloadUrl=URL.createObjectURL(blob),a=document.createElement("a");a.href=downloadUrl,a.download=filename,document.body.appendChild(a),a.click(),document.body.removeChild(a),URL.revokeObjectURL(downloadUrl)})).catch((error=>{spiner.style.display="none",sdWebData.className="bd bd-dg",sdWebData.innerHTML=error}))}